package org.eclipse.rdf4j.federated.algebra;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.federated.EndpointManager;
import org.eclipse.rdf4j.federated.FederationContext;
import org.eclipse.rdf4j.federated.algebra.StatementSource.StatementSourceType;
import org.eclipse.rdf4j.federated.endpoint.Endpoint;
import org.eclipse.rdf4j.federated.structures.QueryInfo;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

public class FedXPlanCloneTest {
	@Test
	public void naryCloneOwnsItsArgumentsAndParentReferences() {
		NJoin original = new NJoin(new ArrayList<>(List.of(new SingletonSet(), new SingletonSet())),
				mock(QueryInfo.class));
		NJoin copy = original.clone();
		assertThat(copy.getArgs()).isNotSameAs(original.getArgs());
		for (int i = 0; i < original.getNumberOfArguments(); i++) {
			assertThat(copy.getArg(i)).isNotSameAs(original.getArg(i));
			assertThat(copy.getArg(i).getParentNode()).isSameAs(copy);
			assertThat(original.getArg(i).getParentNode()).isSameAs(original);
		}
	}

	@Test
	public void exclusiveGroupClonePreservesAnnotationsAndOwnsStatements() {
		QueryInfo query = mock(QueryInfo.class);
		FederationContext federation = mock(FederationContext.class);
		EndpointManager endpoints = mock(EndpointManager.class);
		when(query.getFederationContext()).thenReturn(federation);
		when(federation.getEndpointManager()).thenReturn(endpoints);
		when(endpoints.getEndpoint("member")).thenReturn(mock(Endpoint.class));
		StatementSource source = new StatementSource("member", StatementSourceType.REMOTE);
		ExclusiveStatement statement = new ExclusiveStatement(
				new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")),
				source, query);
		ExclusiveGroup original = new ExclusiveGroup(List.of(statement), source, query);
		ExclusiveGroup copy = original.clone();
		assertThat(copy.getOwner()).isEqualTo(source);
		assertThat(copy.getQueryInfo()).isSameAs(query);
		ExclusiveStatement copied = (ExclusiveStatement) copy.getExclusiveExpressions().getFirst();
		assertThat(copied).isNotSameAs(statement);
		assertThat(copied.getParentNode()).isSameAs(copy);
		assertThat(statement.getParentNode()).isSameAs(original);
		copied.replaceChildNode(copied.getSubjectVar(),
				Var.of("s", SimpleValueFactory.getInstance().createIRI("urn:s")));
		assertThat(statement.getScope()).isEqualTo(StatementPattern.Scope.DEFAULT_CONTEXTS);
		assertThat(statement.getSubjectVar().hasValue()).isFalse();
	}
}
